diff --git a/sistema/sistema.cpp b/sistema/sistema.cpp
index 77b0c66..f5d3c60 100644
--- a/sistema/sistema.cpp
+++ b/sistema/sistema.cpp
@@ -1853,6 +1853,124 @@ void process_dump(des_proc* p, log_sev sev)


 // ( SOLUZIONE 2025-06-05
+
+extern "C" void c_swap_out(natl pid, char *buf)
+{
+    // Troja check: buf must be accessible and writable in user shared memory
+    if (!c_access((vaddr)(uintptr_t)buf, DIM_USR_STACK, true)) {
+        c_abort_p();
+        return;
+    }
+
+    // Troja check: pid must be in valid range
+    if (pid > MAX_PROC_ID) {
+        c_abort_p();
+        return;
+    }
+
+    // Process doesn't exist
+    if (!proc_table[pid]) {
+        esecuzione->contesto[I_RAX] = false;
+        return;
+    }
+
+    des_proc* p = proc_table[pid];
+
+    // Can't swap out system process
+    if (p->livello == LIV_SISTEMA) {
+        c_abort_p();
+        return;
+    }
+
+    // Can't swap out self
+    if (p == esecuzione) {
+        c_abort_p();
+        return;
+    }
+
+    // Already swapped out
+    if (p->swapped_out) {
+        esecuzione->contesto[I_RAX] = false;
+        return;
+    }
+
+    // Copy user stack from target process to buffer via FM window
+    vaddr base = fin_utn_p - DIM_USR_STACK;
+    for (natq i = 0; i < DIM_USR_STACK; i += DIM_PAGINA) {
+        paddr phys = trasforma(p->cr3, base + i);
+        if (phys) {
+            memcpy(buf + i, reinterpret_cast<char*>(phys), DIM_PAGINA);
+        } else {
+            memset(buf + i, 0, DIM_PAGINA);
+        }
+    }
+
+    // Destroy user stack (unmap and deallocate frames)
+    distruggi_pila(p->cr3, fin_utn_p, DIM_USR_STACK);
+
+    p->swapped_out = true;
+    esecuzione->contesto[I_RAX] = true;
+}
+
+extern "C" void c_swap_in(natl pid, const char *buf)
+{
+    // Troja check: buf must be accessible in user shared memory
+    if (!c_access((vaddr)(uintptr_t)buf, DIM_USR_STACK, false)) {
+        c_abort_p();
+        return;
+    }
+
+    // Troja check: pid must be in valid range
+    if (pid > MAX_PROC_ID) {
+        c_abort_p();
+        return;
+    }
+
+    // Process doesn't exist
+    if (!proc_table[pid]) {
+        esecuzione->contesto[I_RAX] = false;
+        return;
+    }
+
+    des_proc* p = proc_table[pid];
+
+    // Can't swap in system process
+    if (p->livello == LIV_SISTEMA) {
+        c_abort_p();
+        return;
+    }
+
+    // Must be swapped out
+    if (!p->swapped_out) {
+        esecuzione->contesto[I_RAX] = false;
+        return;
+    }
+
+    // Create user stack with new frames
+    if (!crea_pila(p->cr3, fin_utn_p, DIM_USR_STACK, LIV_UTENTE)) {
+        esecuzione->contesto[I_RAX] = false;
+        return;
+    }
+
+    // Copy buffer to new stack via FM window
+    vaddr base = fin_utn_p - DIM_USR_STACK;
+    for (natq i = 0; i < DIM_USR_STACK; i += DIM_PAGINA) {
+        paddr phys = trasforma(p->cr3, base + i);
+        memcpy(reinterpret_cast<char*>(phys), buf + i, DIM_PAGINA);
+    }
+
+    p->swapped_out = false;
+
+    // If the process was scheduled while swapped out, reinsert in ready queue
+    if (p->scheduled) {
+        p->scheduled = false;
+        inspronti();           // preemption
+        inserimento_lista(pronti, p);
+        schedulatore();        // preemption
+    }
+
+    esecuzione->contesto[I_RAX] = true;
+}
 //   SOLUZIONE 2025-06-05 )


